#!/bin/bash
# Microbench top-level build: cube / vector / memory / scalar / fixp
# Each category has its own compile.all that builds every case.
# fixp is hand-maintained (one source, 64 -D modes); the other four are
# table-generated by gen_cases.py.

CATEGORY=${1:-all}

compile_cube()   { echo ""; echo ">>> matrix (TMA/CUBE direct)"; (cd cube && bash compile.all); }
compile_vector() { echo ""; echo ">>> vector (TEPL)";     (cd vector && bash compile.all); }
compile_memory() { echo ""; echo ">>> memory (TLSU)";     (cd memory && bash compile.all); }
compile_scalar() { echo ""; echo ">>> scalar (GPR ALU)";  (cd scalar && bash compile.all); }
compile_fixp()   { echo ""; echo ">>> fixp (FPATR/quant TMATMUL)"; (cd fixp && bash compile.all); }

case "$CATEGORY" in
    cube)   compile_cube ;;
    vector) compile_vector ;;
    memory) compile_memory ;;
    scalar) compile_scalar ;;
    fixp)   compile_fixp ;;
    all)
        compile_cube
        compile_vector
        compile_memory
        compile_scalar
        compile_fixp
        ;;
    *)
        echo "Usage: $0 [cube|vector|memory|scalar|fixp|all]"
        exit 1
        ;;
esac

echo ""
echo "=========================================="
echo "Microbench build completed for: $CATEGORY"
echo "=========================================="
